    return self.none(Plans.CHECKPOINT_PHASE_END.create(n=self.plan_id, phase=self.phase))

def on_session_started(self, event: SessionStarted, settings: Settings) -> Transition:
    from journal.features.plans.feature import Plans
    if self.checkpoint_pause:
        return self.none(Plans.CHECKPOINT_PHASE_END.create(n=self.plan_id, phase=self.phase))
    return super().on_session_started(event, settings)

def on_tool_starting(self, event: ToolStarting, settings: Settings) -> Transition:
    return self.none() if self.checkpoint_pause else super().on_tool_starting(event, settings)

def on_task_started(self, event: TaskStarted, settings: Settings) -> Transition:
    from journal.features.tasks.feature import Tasks
    if event.task_id not in event.data.part(Tasks).agent_tasks:
        return self.none()
    return self.swap(replace(self, task_id=event.task_id, checkpoint_pause=False, phase=0, logged_at=event.time, edits=0))

def on_task_closed(self, event: TaskClosed, settings: Settings) -> Transition:
    from journal.features.plans.feature import Plans
    if event.task_id != self.task_id:
        return self.none()
    started = event.data.part(Plans).started
    if started is not None and started.checkpoint_pause:
        return self.swap(replace(self, task_id=0, origin_state=event.task_id, checkpoint_pause=True, phase=started.checkpoint_phase))
    return self.swap(replace(self, task_id=0, origin_state=event.task_id))

def on_plan_finished(self, event: PlanFinished, settings: Settings) -> Transition:
    from journal.features.plans.feature import Plans
    return self.pop(Plans.PLAN_FINISHED.create(n=event.plan_id)) if event.plan_id == self.plan_id else self.none()

def on_plan_postponed(self, event: PlanPostponed, settings: Settings) -> Transition:
    from journal.features.plans.feature import Plans
    if event.plan_id != self.plan_id:
        return self.none()
    return self.pop(Plans.PLAN_POSTPONED.create(n=event.plan_id)) if event.user_origin else self.pop()

def on_plan_abandoned(self, event: PlanAbandoned, settings: Settings) -> Transition:
    from journal.features.plans.feature import Plans
    if event.plan_id != self.plan_id:
        return self.none()
    return self.pop(Plans.PLAN_ABANDONED.create(n=event.plan_id)) if event.user_origin else self.pop()

def on_resume(self, data: FeatureData, settings: Settings) -> tuple[Nudge, ...] | Transition:
    from journal.features.plans.feature import Plans
    started = data.part(Plans).started
    if started is None or started.plan_id != self.plan_id:
        return self.pop()
    if started.started_task and started.started_task != self.task_id:
        return self.swap(replace(self, task_id=started.started_task, checkpoint_pause=False, phase=0, edits=0))
    return super().on_resume(data, settings)
def on_task_logged(self, event: TaskLogged, settings: Settings) -> Transition:
    return self.swap(self.logged(event.time)) if event.task_id

import {reactive} from "vue";
import {startFloors, stopFloors} from "../figure/floors.js";

// The figure's body, one state, and the loop that steps it every frame against the floors the floors loop reads (figure/floors.js):
// - place: where it rests, or last rested while it travels, a spot on a line with the posture it takes there (places.js)
// - at: the picture's left and top in the window, kept at the place while it rests and stepped along each leg while it travels
// - trip: the trip in hand, or null: the spot it goes to with that spot's footing, and once it sets off its legs still to go (places.js
//   tripTo); `started` once it stands ready to travel, `moves` while a leg carries it, and `hopping` and `clip` for the leg it is on or
//   sets off on next
// - leg: the leg under way, and walk: where and when it set off and the floor a walk keeps to
// - footing: what it rests on (figure/floors.js footingOn), watched each frame, also while it gets ready to go; null once it sets off,
//   when the trip keeps the footing of the spot it goes to
// - airborne: the fall it is in, or null; landing: the land clip plays once after a jump or a fall, unless it goes on to hang
// - arriving, leaving, here: the voice's entrance plays when its figure appears, and its exit when the environment's agent goes
// - slide: the picture easing to its new place as the posture changes, from where, to where and since when, or null; rested: the posture
//   it rests in; way: the way its last trip went
// `frame` steps the body once; it runs each frame while the figure is here and the page is shown.
export function useFigureBody(frame) {
    const body = reactive({
        place: {x: 0, y: 0, posture: "stand", view: null, on: null},
        at: {x: 0, y: 0},
        trip: null,
        leg: {x: 0, y: 0, ms: 0, lead: 0, easing: "linear"},
        walk: {from: {x: 0, y: 0}, began: 0, on: null},
        footing: null,
        airborne: null,
        landing: false,
        arriving: false,
        leaving: false,
        here: false,
        slide: null,
        rested: "stand",
        way: 0,
    });
    let looped = 0;
    const loop = () => {
        looped = requestAnimationFrame(loop);
        if (body.here && !document.hidden) frame();
    };
    function stop() {
        cancelAnimationFrame(looped);
        stopFloors();
    }
    function start() {
        stop();
        startFloors();
        looped = requestAnimationFrame(loop);
    }
    return {body, start, stop};
}

